{

"kind": "propose",
"summary": "Adjust liveness probe timeout to accommodate slower startup",
"hypotheses": [
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "Pods are killed during startup due to liveness probe timeout",
        "supporting": ["killed_during_startup", "probe_kills"],
        "contradicting": ["crashed_on_its_own"],
        "missing": ["probe_timeouts"],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "Need more data to confirm probe timing vs app startup duration",
        "supporting": ["rollout_recent"],
        "contradicting": ["killed_during_startup"],
        "missing": ["container_logs_tail"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "finance",
        "name": "ledger",
        "uid": "uid-deployment-ledger"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Allow liveness probe to wait longer for app startup before failing",
    "rationale": "The liveness probe timeout of 1s is too short for the app's startup duration of 32s. Increasing timeoutSeconds to 5s will give the app sufficient time to start before the probe fails, preventing premature restarts.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
    "cited_predicates": ["killed_during_startup", "probe_kills", "crashed_on_its_own"]
}
}
